 * Virtual-list windowing math. Pure functions, no DOM.
 *
 * Supports variable item heights via `getItemHeight(index)`. A module-scoped
 * prefix-sum cache makes repeated `computeRange` calls O(log n): the visible
 * range is located with binary searches over the cached prefix sums instead of
 * re-measuring every item. When heights change, call `invalidateFrom(index)`
 * so only the affected suffix is recomputed on the next call.
 */

export interface ComputeRangeParams {
  /** Current scroll position in pixels. Clamped to [0, totalHeight - viewportHeight]. */
  scrollTop: number;
  /** Visible viewport height in pixels. */
  viewportHeight: number;
  /** Total number of items. */
  itemCount: number;
  /** Extra items rendered above/below the visible range. Defaults to 0. */
  overscan?: number;
  /** Returns the height of a single item. Must be a stable, pure function of `index`. */
  getItemHeight: (index: number) => number;
}

export interface WindowRange {
  /** First index to render (after overscan expansion). */
  startIndex: number;
  /** Last index to render (after overscan expansion). -1 when itemCount === 0. */
  endIndex: number;
  /** Pixel offset of `startIndex` from the top of the list. */
  offsetTop: number;
  /** Total pixel height of all items. */
  totalHeight: number;
}

interface PrefixCache {
  /** The exact getItemHeight reference the cache was built for. */
  fn: (index: number) => number;
  /** Per-index heights for indices [0, heights.length). */
  heights: number[];
  /** prefix[i] = sum of heights[0..i-1]; prefix.length === heights.length + 1. */
  prefix: number[];
  /**
   * First index whose height/prefix may be stale (Infinity when fully clean).
   * Lazily recomputed on the next computeRange call.
   */
  dirtyFrom: number;
}

let cache: PrefixCache | null = null;

function assertFinite(value: number, name: string): void {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be a finite number, got ${String(value)}`);
  }
}

function buildFresh(fn: (index: number) => number, itemCount: number): void {
  const heights = new Array<number>(itemCount);
  for (let i = 0; i < itemCount; i++) {
    const h = fn(i);
    assertFinite(h, `getItemHeight(${i})`);
    if (h < 0) throw new RangeError(`getItemHeight(${i}) returned a negative height: ${h}`);
    heights[i] = h;
  }
  const prefix = new Array<number>(itemCount + 1);
  prefix[0] = 0;
  for (let i = 0; i < itemCount; i++) prefix[i + 1] = prefix[i] + heights[i];
  cache = { fn, heights, prefix, dirtyFrom: Infinity };
}

/** Bring the cache in sync with (fn, itemCount), recomputing only dirty suffixes. */
function ensureCache(fn: (index: number) => number, itemCount: number): PrefixCache {
  if (!cache || cache.fn !== fn) {
    buildFresh(fn, itemCount);
    return cache;
  }

  const c = cache;

  if (c.heights.length > itemCount) {
    // Items removed: truncate; anything dirtied beyond the new end is irrelevant.
    c.heights.length = itemCount;
    c.prefix.length = itemCount + 1;
    if (c.dirtyFrom > itemCount) c.dirtyFrom = Infinity;
  } else if (c.heights.length < itemCount) {
    // Items added: measure only the new tail, mark it dirty so prefixes catch up.
    const prevLen = c.heights.length;
    for (let i = prevLen; i < itemCount; i++) {
      const h = fn(i);
      assertFinite(h, `getItemHeight(${i})`);
      if (h < 0) throw new RangeError(`getItemHeight(${i}) returned a negative height: ${h}`);
      c.heights.push(h);
    }
    if (c.dirtyFrom > prevLen) c.dirtyFrom = prevLen;
  }

  // Lazily repair the dirty suffix (height changes from invalidateFrom).
  if (c.dirtyFrom < itemCount) {
    for (let i = c.dirtyFrom; i < itemCount; i++) {
      const h = fn(i);
      assertFinite(h, `getItemHeight(${i})`);
      if (h < 0) throw new RangeError(`getItemHeight(${i}) returned a negative height: ${h}`);
      c.heights[i] = h;
    }
    for (let i = c.dirtyFrom; i < itemCount; i++) {
      c.prefix[i + 1] = c.prefix[i] + c.heights[i];
    }
    c.dirtyFrom = Infinity;
  }

  return c;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

/**
 * Compute which items should be rendered for the given scroll state.
 *
 * Repeated calls with the same `getItemHeight` reference are O(log n):
 * lookups are binary searches over a cached prefix-sum table, never linear
 * scans or per-item re-measurements. If item heights change after rendering,
 * call {@link invalidateFrom} with the first changed index.
 */
export function computeRange({
  scrollTop,
  viewportHeight,
  itemCount,
  overscan = 0,
  getItemHeight,
}: ComputeRangeParams): WindowRange {
  assertFinite(scrollTop, "scrollTop");
  assertFinite(viewportHeight, "viewportHeight");
  assertFinite(overscan, "overscan");
  if (!Number.isInteger(itemCount) || itemCount < 0) {
    throw new RangeError(`itemCount must be a non-negative integer, got ${itemCount}`);
  }
  if (viewportHeight < 0) throw new RangeError(`viewportHeight must be >= 0, got ${viewportHeight}`);

  if (itemCount === 0) {
    return { startIndex: 0, endIndex: -1, offsetTop: 0, totalHeight: 0 };
  }

  const { prefix } = ensureCache(getItemHeight, itemCount);
  const totalHeight = prefix[itemCount];

  // Clamp scroll position so we never window past the end of the list.
  const maxScrollTop = Math.max(0, totalHeight - viewportHeight);
  const top = clamp(scrollTop, 0, maxScrollTop);
  const bottom = top + viewportHeight;

  // Binary search: smallest s such that item s's bottom edge passes `top`.
  let lo = 0;
  let hi = itemCount - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (prefix[mid + 1] > top) hi = mid;
    else lo = mid + 1;
  }
  let startIndex = lo;

  // Binary search: largest e such that item e's top edge is before `bottom`.
  lo = 0;
  hi = itemCount - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (prefix[mid] < bottom) lo = mid;
    else hi = mid - 1;
  }
  let endIndex = lo;

  // Expand by overscan at both edges, clamped to the list bounds.
  startIndex = Math.max(0, startIndex - overscan);
  endIndex = Math.min(itemCount - 1, endIndex + overscan);

  return { startIndex, endIndex, offsetTop: prefix[startIndex], totalHeight };
}

/**
 * Mark heights from `index` onward as stale. The affected suffix is
 * re-measured (and its prefix sums rebuilt) on the next `computeRange`
 * call — earlier indices keep their cached measurements.
 */
export function invalidateFrom(index: number): void {
  if (!Number.isInteger(index)) {
    throw new RangeError(`index must be an integer, got ${index}`);
  }
  if (!cache) return;
  cache.dirtyFrom = Math.min(cache.dirtyFrom, Math.max(0, index));
}

/** Test-only: drop all cached state. */
export function __resetCache(): void {
  cache = null;
}
